CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS schema_version (id BIGSERIAL PRIMARY KEY, version INTEGER NOT NULL UNIQUE, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_user (id BIGSERIAL PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(200) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'user', status VARCHAR(20) NOT NULL DEFAULT 'active', can_manage_accounts BOOLEAN NOT NULL DEFAULT false, can_view_cash_flow BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_login_session (id BIGSERIAL PRIMARY KEY, sid VARCHAR(64) NOT NULL UNIQUE, user_id BIGINT NOT NULL REFERENCES app_user(id), username VARCHAR(80) NOT NULL, role VARCHAR(20) NOT NULL, ip VARCHAR(80), user_agent VARCHAR(300), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), ended_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS account (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, type VARCHAR(50) NOT NULL, category VARCHAR(20) NOT NULL, currency VARCHAR(10) NOT NULL DEFAULT 'PKR', balance_minor BIGINT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS client (id BIGSERIAL PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, phone VARCHAR(30), address VARCHAR(200), category VARCHAR(50), opening_balance_minor BIGINT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS supplier (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, phone VARCHAR(30), address VARCHAR(200), opening_balance_minor BIGINT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS material (id BIGSERIAL PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, category_id BIGINT, unit VARCHAR(20), unit_price_minor BIGINT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cash_flow_entry (id BIGSERIAL PRIMARY KEY, direction VARCHAR(10) NOT NULL CHECK(direction IN ('in','out','transfer')), amount_minor BIGINT NOT NULL CHECK(amount_minor > 0), account_id BIGINT NOT NULL REFERENCES account(id), destination_account_id BIGINT REFERENCES account(id), reference VARCHAR(200), source_type VARCHAR(80), source_id BIGINT, description VARCHAR(200), idempotency_key VARCHAR(200) UNIQUE, revision INTEGER NOT NULL DEFAULT 1, is_void BOOLEAN NOT NULL DEFAULT false, created_by BIGINT REFERENCES app_user(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id UUID PRIMARY KEY, module VARCHAR(50) NOT NULL, action VARCHAR(30) NOT NULL, entity_type VARCHAR(50) NOT NULL, entity_id BIGINT, user_id BIGINT, username VARCHAR(80), reason VARCHAR(500), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_cash_flow_posted ON cash_flow_entry(created_at) WHERE is_void = false;
CREATE INDEX IF NOT EXISTS idx_session_active ON user_login_session(sid) WHERE ended_at IS NULL;
INSERT INTO schema_version(version) VALUES (1) ON CONFLICT (version) DO NOTHING;
